                JObject rq = new JObject();
                rq["AnalysisId"] = Sess._auditAnalysisId;
                rq["SessionId"] = Sess._traceId;
                rq["TurnIndex"] = 0;
                if (who != null)
                {
                    if (who["user"] != null) { rq["UserName"] = who["user"]; }
                    if (who["role"] != null) { rq["UserRole"] = who["role"]; }
                    if (who["ip"] != null) { rq["UserIp"] = who["ip"]; }
                }
                rq["RequestedAtUtc"] = Sess._reqStartUtc.ToString("o");
                rq["SiteId"] = CtxLong(ctx, "siteId");
                rq["SiteName"] = GetCtx(ctx, "station");
                try { rq["ServerNode"] = Environment.MachineName; } catch { }
                rq["ApiEndpoint"] = "AnalyzeAlert";
                rq["ControllerVersion"] = ComponentVersion;
                rq["Engine"] = Sess._provider ?? "";
                rq["Provider"] = ProviderKind;
                if (which != null)
                {
                    if (which["model"] != null) { rq["ModelId"] = which["model"]; }
                    if (which["thinking"] != null) { rq["ThinkingEnabled"] = which["thinking"]; }
                    if (which["roleGated"] != null) { rq["GatedByRole"] = which["roleGated"]; }
                }
                if (rq["ModelId"] == null) { rq["ModelId"] = ReadStr("DeepSeekModel", ""); }
                rq["RequestType"] = "verdict";
                rq["AlertId"] = CtxLong(ctx, "alertId");
                rq["AlertType"] = GetCtx(ctx, "alertType");
                rq["CauseCode"] = GetCtx(ctx, "causeCode");
                rq["AssetId"] = CtxLong(ctx, "assetId");
                rq["AssetName"] = GetCtx(ctx, "assetName");
                if (!string.IsNullOrEmpty(Sess._lastPromptFull)) { rq["SystemPrompt"] = PgSafe(Sess._lastPromptFull, 0); }
                rq["RespondedAtUtc"] = DateTime.UtcNow.ToString("o");   // required by the server

                JObject r = AuditPost("/api/AIRequest/Start", rq);
                long reqId = 0;
                if (r != null && r["RequestId"] != null) { long.TryParse(r["RequestId"].ToString(), out reqId); }
                if (reqId <= 0) { McpDrain(Sess._traceId); return; }   // drop the calls, never orphan them

                JObject rc = new JObject();
                rc["RequestId"] = reqId;
                rc["AnalysisId"] = Sess._auditAnalysisId;
                rc["RespondedAtUtc"] = DateTime.UtcNow.ToString("o");
                if (when != null && when["totalMs"] != null) { rc["LatencyMs"] = when["totalMs"]; }
                if (cost != null)
                {
                    if (cost["tokIn"] != null) { rc["TokensIn"] = cost["tokIn"]; }
                    if (cost["tokOut"] != null) { rc["TokensOut"] = cost["tokOut"]; }
                    if (cost["costUsdEst"] != null) { rc["EstCostUsd"] = cost["costUsdEst"]; }
                    if (cost["toolCalls"] != null) { rc["McpToolCallCount"] = cost["toolCalls"]; }
                    if (cost["iterations"] != null) { rc["IterationCount"] = cost["iterations"]; }
                }
                if (Sess._lastVerdictSummary != null)
                {
                    if (Sess._lastVerdictSummary["verdict"] != null) { rc["Verdict"] = Sess._lastVerdictSummary["verdict"].ToString(); }
                    if (Sess._lastVerdictSummary["confidence"] != null) { rc["Confidence"] = Sess._lastVerdictSummary["confidence"].ToString(); }
                }
                if (Sess._computedVerdict != null && Sess._computedVerdict["class"] != null) { rc["ComputedVerdict"] = Sess._computedVerdict["class"].ToString(); }
                rc["ComputedWon"] = Sess._computedWonLast;
                if (!string.IsNullOrEmpty(Sess._lastResponseFull)) { rc["FullResponseJson"] = PgSafe(Sess._lastResponseFull, 0); }
                AuditPost("/api/AIRequest/Complete", rc);

                // ALL calls of the run in ONE post -- McpCall/Add loops a JSON array server-side.
                List<JObject> calls = McpDrain(Sess._traceId);
                if (calls == null || calls.Count == 0) { return; }
                JArray arr = new JArray();
                for (int i = 0; i < calls.Count; i++)
                {
