                    if (c["ToolResultJson"] != null) { c["ToolResultJson"] = PgSafe(c["ToolResultJson"].ToString(), 0); }
                    arr.Add(c);
                }
                AuditPostArray("/api/AIMcpCall/Add", arr);
                AiLog("INFO", "AUDITDB", "request " + reqId + " + " + arr.Count + " mcp calls written");
